 r.active=true;LONG apply=ChangeDisplaySettingsExW(r.name.c_str(),&desired,nullptr,0,nullptr);DEVMODEW actual{};actual.dmSize=sizeof actual;bool changed=apply==DISP_CHANGE_SUCCESSFUL&&EnumDisplaySettingsExW(r.name.c_str(),ENUM_CURRENT_SETTINGS,&actual,0)&&actual.dmPelsWidth==1920&&actual.dmPelsHeight==1080&&GetSystemMetrics(SM_CXSCREEN)==1920&&GetSystemMetrics(SM_CYSCREEN)==1080;printf("MODE_CONTROL changed_rc=%ld changed_verified=%d active_frequency=%lu\n",apply,changed?1:0,actual.dmDisplayFrequency);fflush(stdout);if(!changed)return 4;
