 bool children=true;for(int i=0;i<3;i++){printf("MODE_CONTROL_PHASE repeat=%d\n",i);fflush(stdout);std::wstring cmd=L"\""+exe+L"\" present 3000 3";STARTUPINFOW si{};si.cb=sizeof si;si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=GetStdHandle(STD_INPUT_HANDLE);si.hStdOutput=GetStdHandle(STD_OUTPUT_HANDLE);si.hStdError=GetStdHandle(STD_ERROR_HANDLE);PROCESS_INFORMATION p{};if(!CreateProcessW(exe.c_str(),&cmd[0],nullptr,nullptr,TRUE,0,nullptr,nullptr,&si,&p)){children=false;break;}DWORD wait=WaitForSingleObject(p.hProcess,60000),code=1;if(wait!=WAIT_OBJECT_0){TerminateProcess(p.hProcess,90);WaitForSingleObject(p.hProcess,10000);children=false;}else if(!GetExitCodeProcess(p.hProcess,&code)||code!=0)children=false;CloseHandle(p.hThread);CloseHandle(p.hProcess);if(!children)break;}
